window.__votdWeek && window.__votdWeek({"week":"2028-07-24","reading":"Alma 36–38","days":[{"d":"2028-07-24","ref":"Alma 36:7","b":"Alma","c":36,"v":7,"he":"וְהִנֵּה דִּבֶּר אֵלֵינוּ כְּקוֹל רַעַם וַתִּרְעַשׁ כׇּל הָאָרֶץ תַּחַת רַגְלֵינוּ וַנִּפֹּל כֻּלָּנוּ אַרְצָה כִּי נָפְלָה עָלֵינוּ אֵימַת יְהוָה׃","en":"And behold, he spake unto us, as it were the voice of thunder, and the whole earth did tremble beneath our feet; and we all fell to the earth, for the fear of the Lord came upon us."},{"d":"2028-07-25","ref":"Alma 36:15","b":"Alma","c":36,"v":15,"he":"הוֹי אָמַרְתִּי מִי־יִתֵּן וְאֶנָּדֶה וְאֶכָּחֵד גַּם נֶפֶשׁ גַּם גוּף לְבִלְתִּי אוּבָא לַעֲמֹד לִפְנֵי אֱלֹהַי לְהִשָּׁפֵט עַל מַעֲשָׂי׃","en":"Oh, thought I, that I could be banished and become extinct both soul and body, that I might not be brought to stand in the presence of my God, to be judged of my deeds."},{"d":"2028-07-26","ref":"Alma 36:18","b":"Alma","c":36,"v":18,"he":"וַיְהִי כַּאֲשֶׁר אָחֲזָה מַחֲשַׁבְתִּי בַּדָּבָר הַזֶּה וָאֶזְעַק בְּלִבִּי הוֹי יֵשׁוּעַ בֶּן־אֱלֹהִים חׇנֵּנִי אֲנִי אֲשֶׁר בִּמְרוֹרַת רוֹשׁ אֲנִי וּמֻקָּף בְּכַבְלֵי מָוֶת עוֹלָם׃","en":"Now, as my mind caught hold upon this thought, I cried within my heart: O Jesus, thou Son of God, have mercy on me, who am in the gall of bitterness, and am encircled about by the everlasting chains of death."},{"d":"2028-07-27","ref":"Alma 37:7","b":"Alma","c":37,"v":7,"he":"וַיהוָה אֱלֹהִים פּוֹעֵל בִּדְבָרִים לְהָבִיא אֶת־עֲצוֹתָיו הַגְּדוֹלוֹת אֲשֶׁר־לְעוֹלָם וּבִדְבָרִים קְטַנִּים מְאֹד יָבִישׁ יְהוָה אֶת־הַחֲכָמִים וּמֵבִיא יְשׁוּעָה לְנַפְשׁוֹת רַבּוֹת׃","en":"And the Lord God doth work by means to bring about his great and eternal purposes; and by very small means the Lord doth confound the wise and bringeth about the salvation of many souls."},{"d":"2028-07-28","ref":"Alma 37:13","b":"Alma","c":37,"v":13,"he":"הוֹי זְכֹר זְכֹר בְּנִי הֵילָמָן מַה קָשׁוֹת מִצְוֹת־אֱלֹהִים וְהוּא אָמַר אִם־תִּשְׁמְרוּ אֶת־מִצְוֹתַי תַּצְלִיחוּ בָּאָרֶץ אַךְ אִם־לֹא תִשְׁמְרוּ אֶת־מִצְוֹתָיו תִּכָּרְתוּ מִלְּפָנָיו׃","en":"O remember, remember, my son Helaman, how strict are the commandments of God. And he said: If ye will keep my commandments ye shall prosper in the land—but if ye keep not his commandments ye shall be cut off from his presence."},{"d":"2028-07-29","ref":"Alma 37:31","b":"Alma","c":37,"v":31,"he":"הֵן וְאָרוּר תִּהְיֶה הָאָרֶץ לְעוֹלָם וָעֶד לְפֹעֲלֵי הַחֹשֶׁךְ וּלְקִשְׁרֵי הַסֵּתֶר עַד־לְהַשְׁמִיד אִם־לֹא יָשׁוּבוּ בְּטֶרֶם יִבְשְׁלוּ׃","en":"Yea, and cursed be the land forever and ever unto those workers of darkness and secret combinations, even unto destruction, except they repent before they are fully ripe."},{"d":"2028-07-30","ref":"Alma 38:4","b":"Alma","c":38,"v":4,"he":"כִּי יָדַעְתִּי כִּי הָיִיתָ בַּכְּבָלִים הֵן וְגַם יָדַעְתִּי כִּי סָקְלוּךָ בַּעֲבוּר הַדָּבָר וַתִּשָּׂא אֶת־כׇּל־הַדְּבָרִים הָאֵלֶּה בְּאֹרֶךְ רוּחַ כִּי הָיָה יְהוָה עִמְּךָ וְעַתָּה יָדַעְתָּ כִּי הִצִּילְךָ יְהוָה׃","en":"For I know that thou wast in bonds; yea, and I also know that thou wast stoned for the word’s sake; and thou didst bear all these things with patience because the Lord was with thee; and now thou knowest that the Lord did deliver thee."}]});
